+	if !hasTokenUsageData(usage) {
+		return
+	}
+	if state.TokenUsage == sessionData.TokenUsage {
+		state.TokenUsage = usage
+	}
+	sessionData.TokenUsage = usage
+	sessionData.ModelUsage = buckets
